local config = {
  ui_story_40200001_1_dialog_content = "Hei, PlayerName...",
  ui_story_40200001_2_dialog_content = "Oh, tunggu, kamu sekarang <color=#FFB400>Tanpa nama</color>, ya?",
  ui_story_40200001_3_dialog_content = "Kamu memegang <color=#FFB400>Covenant of the Hidden Moon</color>.",
  ui_story_40200001_4_dialog_content = "Bawa surat ini nanti malam ke Vortex, tibalah pada tengah malam.",
  ui_story_40200001_5_dialog_content = "Begitu kamu tiba...",
  ui_story_40200001_6_dialog_content = "Semua akan terungkap.",
  ui_story_40200001_7_dialog_content = "Hidden Moon Reading Club",
  ui_story_40200001_8_dialog_content = "(Biar kumulai dari awal...)",
  ui_story_40200001_9_dialog_content = "...",
  ui_story_40200001_10_dialog_content = "Ini hanya undangan ke klub membaca. Kenapa kamu begitu gugup?",
  ui_story_40200001_11_dialog_content = "Namun, ini klub membaca untuk True Order! Mana mungkin itu klub membaca biasa, 'kan?",
  ui_story_40200001_12_dialog_content = "Hei, jangan terlalu menghakimi. Tidak ada yang aneh dan mereka menyambut semua orang.",
  ui_story_40200001_13_dialog_content = "Lantas, kenapa kamu tidak pergi?!",
  ui_story_40200001_14_dialog_content = "Yah, jelas karena aku akan pergi ke acara First Faction.",
  ui_story_40200001_15_dialog_content = "Lagi pula, seseorang harus membuat badut-badut menyebalkan itu tahu diri!",
  ui_story_40200001_16_dialog_content = "Kemudian, aku bisa menghabiskan sore yang luar biasa bersama Victoria... dia sangat cantik.",
  ui_story_40200001_17_dialog_content = "Namun, aku tidak bisa mengabaikan yang lain begitu saja; jika mereka tidak bisa mengumpulkan minimal lima orang untuk klub membaca, mereka akan sangat marah.",
  ui_story_40200001_18_dialog_content = "Sesuatu yang buruk pasti akan terjadi jika mereka tidak mendapatkan apa yang mereka mau!",
  ui_story_40200001_19_dialog_content = "Jika seburuk itu, lalu kenapa kamu tersenyum...",
  ui_story_40200001_20_dialog_content = "Omong-omong... Kupercayakan ini padamu, jadi semoga berhasil!",
  ui_story_40200001_21_dialog_content = "Oh, dan bawalah buku-buku ini. Mungkin kamu membutuhkannya!",
  ui_story_40200001_22_dialog_content = "Aku datang untukmu, Victoria...!",
  ui_story_40200001_23_dialog_content = "(Dia bahkan tidak memberiku kesempatan untuk menolak...)",
  ui_story_40200001_24_dialog_content = "(Begitulah kejadiannya. Segera setelahnya, aku memulai perjalananku ke Vortex.)",
  ui_story_40200001_25_dialog_content = "Menurut alamat di surat itu, aku ada di Vortex sekarang. Selanjutnya, aku harus memasuki bawah tanah yang gelap...",
  ui_story_40200001_26_dialog_content = "Eh...",
  ui_story_40200001_27_dialog_content = "T-tengkorak...",
  ui_story_40200001_28_dialog_content = "Apa ini, alat-alat penyiksaan?! Semuanya dipenuhi paku!",
  ui_story_40200001_29_dialog_content = "D-dan bayangan yang tampak menakutkan itu...",
  ui_story_40200001_30_dialog_content = "PlayerName.",
  ui_story_40200001_31_dialog_content = "<anim type=Shake><size=45>Aaaaaah!!!</size></anim>",
  ui_story_40200001_32_dialog_content = "Mengapa kamu begitu takut?",
  ui_story_40200001_33_dialog_content = "Bonacie?!",
  ui_story_40200001_34_dialog_content = "Tunggu, selama kita di sini, kamu harus memanggilku <color=#FFB400>Lover</color>.",
  ui_story_40200001_35_dialog_content = "Aneh sekali!",
  ui_story_40200001_36_dialog_content = "Ya, sepertinya kamu akan menggantikan Tanpa nama.",
  ui_story_40200001_37_dialog_content = "Eicy adalah orang yang memberitahuku bahwa aku harus datang...",
  ui_story_40200001_38_dialog_content = "Aku tahu, dan aku yakin saat ini dia sedang mencari Lady Victoria.",
  ui_story_40200001_39_dialog_content = "Namun, mengingat kamu hadir menggantikan Nameless, kamu harus mengikuti aturan dan sopan santun untuk menghadiri klub membaca kami.",
  ui_story_40200001_40_dialog_content = "Seperti yang tertulis di surat itu.",
  ui_story_40200001_41_dialog_content = "Pada malam bulan purnama, <color=#FFB400>Maiden</color>, <color=#FFB400>Lover</color>, <color=#FFB400>Lady</color>, <color=#FFB400>Duchess</color>, dan <color=#FFB400>Nameless</color> akan berkumpul.",
  ui_story_40200001_42_dialog_content = "Bersama-sama, mereka akan membaca cerita dan novel di bawah sinar rembulan. Inilah <color=#FFB400>Hidden Moon Reading Club</color>.",
  ui_story_40200001_43_dialog_content = "Itu saja yang kalian lakukan? Membaca buku?",
  ui_story_40200001_44_dialog_content = "Lalu untuk apa semua tengkorak dan alat penyiksaan ini...?",
  ui_story_40200001_45_dialog_content = "Oh, itu milik Nameless yang asli. Tidak ada tempat untuk meletakkannya di ruangannya, jadi dia menaruhnya di sini.",
  ui_story_40200001_46_dialog_content = "Nameless yang asli?",
  ui_story_40200001_47_dialog_content = "Oh, maksudmu Eicy! Aku tidak mengerti kenapa kamu membutuhkan alias untuk klub membaca. Rasanya agak rumit...",
  ui_story_40200001_48_dialog_content = "Rasa ritual sangat penting, PlayerName.",
  ui_story_40200001_49_dialog_content = "Genevieve?",
  ui_story_40200001_50_dialog_content = "Dengan segala hormat, kamu akan menyebutku sebagai <color=#FFB400>Lady</color>.",
  ui_story_40200001_51_dialog_content = "Sama seperti minuman yang kubuat untukmu, identitasku di sini adalah Lady.",
  ui_story_40200001_52_dialog_content = "Di klub membaca ini, kami memilih nama sandi berdasarkan kata-kata yang cocok dengan karakteristik kami.",
  ui_story_40200001_53_dialog_content = "<size=30>Maaf aku terlambat...</size>",
  ui_story_40200001_54_dialog_content = "Bagus, sekarang tinggal menunggu <color=#FFB400>Duchess</color>.",
  ui_story_40200001_55_dialog_content = "Semoga Truth memberkatimu.",
  ui_story_40200001_56_dialog_content = "(Sikare hadir di sini juga...)",
  ui_story_40200001_57_dialog_content = "Karena semua orang sudah hadir, mari kita mulai.",
  ui_story_40200001_58_dialog_content = "Sebelum membahas topik malam ini, mari berterima kasih kepada Nameless baru kita.",
  ui_story_40200001_59_dialog_content = "Berkat semua buku yang terkumpul di Colossus, bahan untuk diskusi dan kesenangan kita sudah lebih dari cukup.",
  ui_story_40200001_60_dialog_content = "T-terima kasih telah membelikan buku yang ingin kubaca...",
  ui_story_40200001_61_dialog_content = "Hah?",
  ui_story_40200001_62_dialog_content = "(Oh, Beryl pasti berbicara soal buku yang ditujukan untuk <color=#FFB400>gadis muda</color>.)",
  ui_story_40200001_63_dialog_content = "Baiklah, topik untuk klub membaca kita malam ini adalah <color=#FFB400>cinta</color>.",
  ui_story_40200001_64_dialog_content = "Aku dulu! Aku dulu!",
  ui_story_40200001_65_dialog_content = "Hmm, ini sungguh malam yang menarik, ya?",
  ui_story_40200001_66_dialog_content = "Aku ahli di bidang ini, jadi tentu saja aku duluan!",
  ui_story_40200001_67_dialog_content = "Teman-teman, apa sebenarnya <color=#FFB400>cinta</color> itu?",
  ui_story_40200001_68_dialog_content = "Aku pernah berpikir cinta itu mulia dan tenang, tetapi juga kacau dan tak terkendali.",
  ui_story_40200001_69_dialog_content = "Seperti kuda hadiah yang berlari liar, atau segelas minuman beralkohol yang terlalu penuh.",
  ui_story_40200001_70_dialog_content = "Karya yang kurekomendasikan untuk topik ini adalah novel berjudul \"Tumultuous Ties\".",
  ui_story_40200001_71_dialog_content = "Buku ini dengan sempurna menunjukkan rumitnya cinta.",
  ui_story_40200001_72_dialog_content = "<color=#FFB400>Pemuda Umbraton</color> yang melarat dan <color=#FFB400>gadis Umbraton</color> yang kesepian jatuh cinta, lalu setuju untuk saling mendukung.",
  ui_story_40200001_73_dialog_content = "Namun, suatu hari, si pemuda dari Umbraton mendapati bahwa dia sebenarnya adalah <color=#FFB400>anak haram dari seorang bangsawan Lumopolis</color>.",
  ui_story_40200001_74_dialog_content = "Bagai mendapat durian runtuh, semua ketenaran, kekayaan, dan kekuasaan yang dia dambakan tiba-tiba tercapai.",
  ui_story_40200001_75_dialog_content = "Kemurnian dan gairah cintanya yang dulu pun kini mulai memudar karenanya; ayahnya juga telah mencarikannya seorang <color=#FFB400>tunangan</color>.",
  ui_story_40200001_76_dialog_content = "Siapa yang akan dia pilih? Gadis Umbraton yang selalu dia kenal dan cintai? Atau pilihan ayahnya, calon pengantin bangsawan?",
  ui_story_40200001_77_dialog_content = "<size=30>Gadis Umbraton, 'kan...?</size>",
  ui_story_40200001_78_dialog_content = "Hah?",
  ui_story_40200001_79_dialog_content = "T-tidak apa-apa, lupakan perkataanku itu...",
  ui_story_40200001_80_dialog_content = "Bagaimana menurutmu, Nameless?",
  ui_story_40200001_81_option_content = "Gadis Umbraton.",
  ui_story_40200001_82_dialog_content = "Cinta adalah emosi yang kuat dan tangguh. Tidak akan mudah terpengaruh oleh gelimang harta.",
  ui_story_40200001_83_option_content = "Gadis bangsawan.",
  ui_story_40200001_84_dialog_content = "Kini dunia mereka sudah berbeda. Perbedaan status ekonomi hanya akan mengurangi rasa cinta mereka.",
  ui_story_40200001_85_dialog_content = "Aku pikir gadis bangsawan akan menjadi pilihan yang lebih baik.",
  ui_story_40200001_86_dialog_content = "Jadi, itu menurutmu, ya?",
  ui_story_40200001_87_dialog_content = "Tidak ada pilihan yang benar atau salah. Jika sesederhana itu, tidak akan ada kesulitan jika terkait cinta.",
  ui_story_40200001_88_dialog_content = "Pada bagian cerita berikutnya, sang gadis Umbraton bertemu dengan <color=#FFB400>seorang bangsawan muda di hutan belantara, dan menyelamatkannya</color>.",
  ui_story_40200001_89_dialog_content = "Cinta di dada sang bangsawan mulai bersemi untuknya.",
  ui_story_40200001_90_dialog_content = "Saat kamu menyelamatkan hidupku, aku jatuh cinta pada pandangan pertama.",
  ui_story_40200001_91_dialog_content = "Namun, aku...",
  ui_story_40200001_92_dialog_content = "Namun, ternyata keluarga bangsawan ini dan keluarga pemuda Umbraton terjebak dalam <color=#FFB400>perseteruan darah</color>...",
  ui_story_40200001_93_dialog_content = "Jika kamu menjadi gadis Umbraton itu, siapa yang akan kamu pilih?",
  ui_story_40200001_94_dialog_content = "<size=30>Siapa? Aduh, ini membingungkan...</size>",
  ui_story_40200001_95_dialog_content = "(Beryl tampaknya bergumam pada dirinya sendiri lagi.)",
  ui_story_40200001_96_option_content = "Sang bangsawan.",
  ui_story_40200001_97_dialog_content = "Cinta pada pandangan pertama, dan meninggalkan cinta lama demi kehidupan baru... Itu juga sama rumitnya.",
  ui_story_40200001_98_dialog_content = "Yang mana pun itu, semuanya bisa menjadi kisah yang baik... Namun, bukan begitu akhir cerita yang sebenarnya.",
  ui_story_40200001_99_dialog_content = "Akhir cerita yang sebenarnya adalah...",
  ui_story_40200001_100_dialog_content = "<color=#FFB400>Gadis Umbraton itu justru berpasangan dengan si gadis bangsawan.</color>",
  ui_story_40200001_101_option_content = "Pemuda Umbraton.",
  ui_story_40200001_102_dialog_content = "Itu akan menjadi jalan yang lebih sulit dari dua jalan yang harus diambil.",
  ui_story_40200001_103_dialog_content = "Bukan hanya tidak akan pernah menerima restu dari keluargamu yang tercinta, kamu juga harus menghadapi permusuhan dan pembalasan dendam dari kedua keluarga di sepanjang hidupmu.",
  ui_story_40200001_104_dialog_content = "Tanpa caramu sendiri, yang kamu perlukan untuk bertahan hidup hanyalah cintamu pada pemuda Umbraton dan rantai masa lalumu.",
  ui_story_40200001_105_dialog_content = "Tentunya ini adalah pilihan yang mulia, tetapi aku khawatir hanya beberapa orang yang bisa melakukannya.",
  ui_story_40200001_106_dialog_content = "Sayangnya, gadis Umbraton tidak membuat pilihan yang sama sepertimu...",
  ui_story_40200001_107_dialog_content = "<color=#FFB400>Pada akhirnya, gadis Umbraton itu justru berpasangan dengan si gadis bangsawan.</color>",
  ui_story_40200001_108_option_content = "Gadis bangsawan.",
  ui_story_40200001_109_dialog_content = "Sungguh pilihan yang tidak biasa.",
  ui_story_40200001_110_dialog_content = "Mengesampingkan moralitas dan etika, dan tidak membiarkan belenggu masa lalu atau masa kini menahanmu...",
  ui_story_40200001_111_dialog_content = "<color=#FFB400>Faktanya, ini adalah akhir cerita yang sebenarnya.</color>",
  ui_story_40200001_112_dialog_content = "Aku tidak pernah mengira Tanpa nama akan begitu tertarik dengan pembahasan ini.",
  ui_story_40200001_113_dialog_content = "Eh? T-tunggu sebentar!",
  ui_story_40200001_114_dialog_content = "Apa yang terjadi di antara mereka berdua? Kenapa mereka pada akhirnya justru bersama?!",
  ui_story_40200001_115_dialog_content = "Kamu harus mencari tahu jawabannya... Dengan membaca sendiri buku itu.",
  ui_story_40200001_116_dialog_content = "Izinkan aku menjelaskan, Tanpa nama tersayang.",
  ui_story_40200001_117_dialog_content = "Lady tidak peduli dengan cinta yang digambarkan dalam buku ini.",
  ui_story_40200001_118_dialog_content = "Dia hanya memedulikan plot yang dilebih-lebihkan dan dibuat-buat yang menjadi ciri khas dari cerita semacam ini.",
  ui_story_40200001_119_dialog_content = "Tokoh yang ditaksir lebih dari satu, perangkap, dan mungkin beberapa elemen sadomasokistik untuk kejutan ekstra.",
  ui_story_40200001_120_dialog_content = "Aku sangat menyarankanmu untuk menghindari bacaan yang tidak sehat semacam ini. Jika tidak, otakmu akan berubah menjadi bubur.",
  ui_story_40200001_121_dialog_content = "Ah, kamu tahu apa? Membaca itu mengasyikkan jika ceritanya seru dan membingungkan seperti ini.",
  ui_story_40200001_122_dialog_content = "Daripada itu, kalian sebaiknya lihat yang kusarankan, Kehidupan Seorang Musisi.",
  ui_story_40200001_123_dialog_content = "Tokoh utama cerita ini, Tn. Litman, adalah pianis hebat yang menggubah \"Litman's Polka\".",
  ui_story_40200001_124_dialog_content = "Seorang yatim piatu tanpa nama ini hidup sebatang kara.",
  ui_story_40200001_125_dialog_content = "Kaki kanannya juga lumpuh sebagian.",
  ui_story_40200001_126_dialog_content = "Di bar kota kecil tanpa nama, dia bermain piano sepanjang hidupnya.",
  ui_story_40200001_127_dialog_content = "Baru setelah kematiannya, gubahannya yang indah ditemukan dan tersebar ke seluruh dunia.",
  ui_story_40200001_128_dialog_content = "Meski hidupnya sungguh suram dan malang, karya musiknya sangat kuat dan membangkitkan semangat.",
  ui_story_40200001_129_dialog_content = "Seorang pemain trompet yang pernah bekerja sama dengannya meninggalkan ukiran di batu nisannya, sebuah kalimat yang berbunyi:",
  ui_story_40200001_130_dialog_content = "Dalam musik, ada kehidupan.",
  ui_story_40200001_131_dialog_content = "Terdengar menarik, tapi... Sepertinya tidak ada unsur cinta dalam cerita ini?",
  ui_story_40200001_132_dialog_content = "Maksudmu, kamu tidak menyadari bahwa Tn. Litman <color=#FFB400>dengan senang hati menghabiskan seluruh hidupnya dengan musiknya</color>?",
  ui_story_40200001_133_dialog_content = "Kamu tidak bisa meminta akhir yang lebih sempurna!",
  ui_story_40200001_134_dialog_content = "Meski benar kamu bisa melihat jenis cinta dalam buku ini, aku khawatir kisah cintanya tidak terlalu dalam.",
  ui_story_40200001_135_dialog_content = "Buku rekomendasiku adalah, \"A Thousand Years of Silence\".",
  ui_story_40200001_136_dialog_content = "Buku ini menceritakan kisah seorang tukang bangunan yang tidak bisa menua atau mati, dan bagaimana dia mengatasi umurnya yang panjang.",
  ui_story_40200001_137_dialog_content = "Setelah kematian kekasih terakhirnya...",
  ui_story_40200001_138_dialog_content = "Dia mengabdikan seribu tahun berikutnya untuk membangun mausoleum bawah tanah yang sangat besar untuk dirinya sendiri, dengan kedalaman ratusan lantai, dan pada akhirnya jatuh ke dalam tidur yang lelap di bagian paling bawah.",
  ui_story_40200001_139_dialog_content = "Generasi selanjutnya menemukan makam tukang bangunan ini dan terpesona oleh keahliannya yang sangat indah. Tukang bangunan itu kemudian dipuja sebagai pendiri arsitektur.",
  ui_story_40200001_140_dialog_content = "Kurasa sang protagonis benar-benar memahami <color=#FFB400>esensi cinta</color>.",
  ui_story_40200001_141_dialog_content = "Terbentang melintasi ruang dan waktu, cinta ada di mana-mana sekaligus tidak ada di mana-mana.",
  ui_story_40200001_142_dialog_content = "Mungkin hanya sesuatu yang sekukuh Truth yang bisa disebut cinta.",
  ui_story_40200001_143_dialog_content = "Sekarang giliranmu, Snowball- maksudku, Tanpa nama. Aduh, julukan Snowball jauh lebih cocok untukmu...",
  ui_story_40200001_144_dialog_content = "G-giliranku?",
  ui_story_40200001_145_dialog_content = "Lagi pula, ini klub membaca, jadi sekarang giliranmu untuk berbagi buku kepada kami. Atau jangan-jangan... Kamu tidak menyiapkannya?",
  ui_story_40200001_146_dialog_content = "Kami tidak berniat membuatmu malu atau apa, tetapi... Apa kamu tidak membawa buku?",
  ui_story_40200001_147_dialog_content = "Bagaimana dengan buku-buku yang diberikan Nameless terdahulu? Kamu bisa membacanya.",
  ui_story_40200001_148_dialog_content = "O-oh, ya.",
  ui_story_40200001_149_dialog_content = "Biar kulihat... Tunggu sebentar, buku-buku ini...",
  ui_story_40200001_150_dialog_content = "(\"How to Cultivate Tentacles\"? \"My Favorite Skeleton\"?? \"Interrogations and Blood: A Love Story\"???)",
  ui_story_40200001_151_dialog_content = "(Peringatan: Tidak ditujukan untuk pembaca di bawah umur...)",
  ui_story_40200001_152_dialog_content = "(...)",
  ui_story_40200001_153_dialog_content = "<size=45>(Astaga, buku macam apa yang kamu berikan padaku, Eicy!?)</size>",
  ui_story_40200001_154_dialog_content = "Ayolah. Bagikan kepada grup.",
  ui_story_40200001_155_dialog_content = "Sepertinya aku tidak bisa!",
  ui_story_40200001_156_dialog_content = "D-dengar! Judul buku ini bahkan telah dicoret dengan pena! Aku yakin ini tidak layak dibagikan!",
  ui_story_40200001_157_dialog_content = "Baiklah, dalam hal preferensi, dia tidak punya buku yang layak.",
  ui_story_40200001_158_dialog_content = "Namun, berbagi adalah bagian penting dari klub membaca kita, tanpa terkecuali Snowball. Sekarang, bacakan untuk kami dengan bagus dan nyaring.",
  ui_story_40200001_159_dialog_content = "Ini adalah aturan yang tidak boleh dilanggar di Hidden Moon Reading Club.",
  ui_story_40200001_160_dialog_content = "Aku... Aku...",
  ui_story_40200001_161_dialog_content = "Sini, aku saja...",
  ui_story_40200001_162_dialog_content = "Hah?",
  ui_story_40200001_163_dialog_content = "Aku bisa menggantikan PlayerName... Aku akan menggantikannya berbagi.",
  ui_story_40200001_164_dialog_content = "Sungguh suatu kejutan! Aku belum pernah melihat Maiden mengambil inisiatif semacam itu!",
  ui_story_40200001_165_dialog_content = "Silakan, Maiden.",
  ui_story_40200001_166_dialog_content = "Yang kupahami tentang cinta adalah... <color=#FFB400>Romansa</color>...",
  ui_story_40200001_167_dialog_content = "Dibandingkan pemahaman orang lain, pemahamanku mungkin tampak tidak penting...",
  ui_story_40200001_168_dialog_content = "Tidak apa-apa, katakan saja apa yang ingin kamu katakan, kami akan mendengarkan.",
  ui_story_40200001_169_dialog_content = "Aku merekomendasikan buku ini, \"The Viridian Grove\".",
  ui_story_40200001_170_dialog_content = "Buku ini menceritakan seorang seniman yang depresi, yang bertemu dengan seorang gadis yang tampak sedih saat membuat sketsa jauh di dalam hutan.",
  ui_story_40200001_171_dialog_content = "Meski seniman ini baru saja bertemu dengannya, dia jatuh cinta pada pandangan pertama...",
  ui_story_40200001_172_dialog_content = "Lalu, dia mulai membuat sketsa gadis itu dengan pensilnya.",
  ui_story_40200001_173_dialog_content = "Awalnya, gadis itu sungguh malu dan tidak mau berhubungan dengan sang seniman...",
  ui_story_40200001_174_dialog_content = "Namun, seiring waktu, sang gadis mulai melihat kecantikannya di sketsa sang seniman.",
  ui_story_40200001_175_dialog_content = "Setelahnya, mereka mulai mengalami segala macam pengalaman pertama bersama...",
  ui_story_40200001_176_dialog_content = "Dalam prosesnya, mereka perlahan tumbuh dan mengatasi ketidaksempurnaan diri.",
  ui_story_40200001_177_dialog_content = "...",
  ui_story_40200001_178_dialog_content = "...",
  ui_story_40200001_179_dialog_content = "...",
  ui_story_40200001_180_dialog_content = "K-kamu tidak menyukainya? Haruskah aku memilih buku yang lain?",
  ui_story_40200001_181_dialog_content = "Tidak, kurasa ceritanya sangat bagus.",
  ui_story_40200001_182_dialog_content = "... Oh, benarkah?",
  ui_story_40200001_183_dialog_content = "Beryl masih sangat muda, 'kan? Seorang gadis yang jujur dan terus terang.",
  ui_story_40200001_184_dialog_content = "Gagasan cinta bagi anak muda begitu murni dan membahagiakan, 'kan?",
  ui_story_40200001_185_dialog_content = "Namun, itu tidak ada salahnya, tahu? Pikirkan semua lagu yang pernah ditulis tentang cinta yang manis dan suci.",
  ui_story_40200001_186_dialog_content = "Meski Tn. Litman tidak pernah menikah seumur hidupnya...",
  ui_story_40200001_187_dialog_content = "Dia menggubah salah satu waltz terindah dalam sejarah, yang berjudul \"The Joyful Bride\".",
  ui_story_40200001_188_dialog_content = "Memikirkannya saja hampir membuatku ingin jatuh cinta.",
